#include <vector>

namespace all_your_base {

std::vector<unsigned int> convert(unsigned int base,
                                  const std::vector<unsigned int>& digits,
                                  unsigned int new_base);

}  // namespace all_your_base

#endif // ALL_YOUR_BASE_H
EOF
cat > all_your_base.cpp <<'EOF'
#include "all_your_base.h"

#include <stdexcept>

namespace all_your_base {

std::vector<unsigned int> convert(unsigned int base,
                                  const std::vector<unsigned int>& digits,
                                  unsigned int new_base) {
    if (base < 2) {
        throw std::invalid_argument("input base must be at least 2");
    }
    if (new_base < 2) {
        throw std::invalid_argument("output base must be at least 2");
    }

    unsigned long long value = 0;
    for (unsigned int digit : digits) {
        if (digit >= base) {
            throw std::invalid_argument("digit is out of range for input base");
        }
        value = value * base + digit;
    }

    if (value == 0) {
        return {};
    }

    std::vector<unsigned int> result;
    while (value > 0) {
        result.insert(result.begin(), static_cast<unsigned int>(value % new_base));
        value /= new_base;
    }

    return result;
}

}  // namespace all_your_base
EOF
echo "=== files written ===" && nl -ba all_your_base.h && nl -ba all_your_base.cpp

