#include "all_your_base.h"
#include <boost/multiprecision/cpp_int.hpp>
#include <iostream>
#include <random>
#include <vector>
using boost::multiprecision::cpp_int;
using namespace all_your_base;

static std::vector<unsigned int> ref(unsigned int base,
                                     const std::vector<unsigned int>& digits,
                                     unsigned int out) {
    cpp_int v = 0;
    for (unsigned int d : digits) v = v * base + d;
    if (v == 0) return {};
    std::vector<unsigned int> r;
    while (v > 0) { r.insert(r.begin(), static_cast<unsigned int>(v % out)); v /= out; }
    return r;
}

int main() {
    std::mt19937 rng(12345);
    int fails = 0;
    for (int t = 0; t < 4000; ++t) {
        unsigned int base = 2 + rng() % (t % 50 == 0 ? 200000u : 30u);
        unsigned int out  = 2 + rng() % (t % 50 == 0 ? 200000u : 30u);
        size_t len = rng() % (t % 7 == 0 ? 300 : 40);
        std::vector<unsigned int> d(len);
        for (auto& x : d) x = rng() % base;
        std::vector<unsigned int> got = convert(base, d, out);
        std::vector<unsigned int> exp = ref(base, d, out);
        if (got != exp) {
            if (++fails <= 3) {
                std::cout << "MISMATCH base=" << base << " out=" << out << " len=" << len
                          << " got_size=" << got.size() << " exp_size=" << exp.size() << "\n";
            }
        }
    }
    std::cout << (fails == 0 ? "RANDOMIZED DIFF OK (4000 cases)\n" : "FAILURES\n");
    return fails == 0 ? 0 : 1;
}
